/*==========================================
 Support Engineering Blog
 Version : 1.0.0
 Build   : 2026-07-29T19:50:03.736Z
==========================================*/

/* Blogger Integration */

/* ==========================================================================
   SEDS Blogger Integration
   File: blogger-base.css
   Purpose:
   Bridges Blogger's Essential Light theme with the
   Support Engineering Design System (SEDS).

   This file should contain only global Blogger overrides
   and integration styles.

   Widget-specific styling belongs in:
   - blogger-header.css
   - blogger-navigation.css
   - blogger-article.css
   ========================================================================== */

   /* ==========================================================================
   Blogger Foundation
   ========================================================================== */

.page {
    background: var(--surface-primary);
    color: var(--text-primary);
    min-height: 100vh;
}

.page_body {
    max-width: 1280px;
    margin-inline: auto;
}

.centered {
    width: min(100%, 1200px);
    margin-inline: auto;
    padding-inline: var(--space-6);
}

img {
    max-width: 100%;
    height: auto;
}

a {
    color: var(--primary);
    text-decoration: none;
    transition: color .2s ease;
}

a:hover {
    color: var(--primary-dark);
}

a:focus-visible,
button:focus-visible,
input:focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}
/* ==========================================================================
   Header Layout
   ========================================================================== */

.centered-top {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: var(--space-6);
    min-height: 72px;
}

.blog-name {
    margin: 0;
    padding-block: var(--space-4);
}

.centered {
    width: min(100%, 1200px);
    margin-inline: auto;
    padding-inline: var(--space-6);
}

.sticky .centered-top {
    min-height: 64px;
}

.blog-name {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-8);
}
/* ==========================================================================
   SEDS Blogger Integration
   File: blogger-header.css

   Purpose:
   Header branding and identity.

   Controls:
   - Logo
   - Blog title
   - Description
   - Branding spacing
   - Sticky branding
   ========================================================================== */

   /* ==========================================================================
   Header Widget
   ========================================================================== */

.header-widget {
    display: flex;
    align-items: center;
    gap: var(--space-4);
}

.blog-name {
    display: flex;
    align-items: center;
    gap: var(--space-6);
}

.Header h1 {
    margin: 0;
    font-family: var(--font-heading);
    font-size: var(--font-size-4xl);
    font-weight: 700;
    line-height: 1.2;
}

.Header p {
    margin-top: var(--space-2);
    color: var(--text-secondary);
}

.sticky .Header h1 {
    font-size: var(--font-size-xl);
}

.sticky .Header p {
    display: none;
}

.header-widget img {
    height: 40px;
    width: auto;
}
